function row = compute_core32_metrics_v1(sim,fit,cfg,method,rep,seed,runtime_seconds)
%COMPUTE_CORE32_METRICS_V1 Fixed-parameter metrics plus selector diagnostics.
method=string(method);
if isfield(fit,'valid') && fit.valid
    truth=sim.labels(:); out=logical(sim.outlier(:)); in=~out;
    pred=fit.labels(:); trim=logical(fit.trim(:));
    ari=adjusted_rand_index_v1(truth(in),pred(in));
    tp=sum(trim&out); fp=sum(trim&~out); fn=sum(~trim&out);
    if any(out)
        prec=tp/max(tp+fp,1); rec=tp/max(tp+fn,1); f1=2*prec*rec/max(prec+rec,eps);
    else
        prec=NaN; rec=NaN; f1=NaN;
    end
    trim_count=sum(trim);
else
    ari=NaN; prec=NaN; rec=NaN; f1=NaN;
    tp=NaN; fp=NaN; fn=NaN; trim_count=NaN;
end
row=table(cfg.scenario_id,rep,seed,method,cfg.n,cfg.p,cfg.p_over_n,cfg.r0,cfg.c0, ...
    string(cfg.arm),string(cfg.difficulty),cfg.delta,cfg.rho,string(cfg.contamination),cfg.alpha0, ...
    ari,prec,rec,f1,tp,fp,fn,trim_count, ...
    field_or(fit,'objective',NaN),field_or(fit,'iterations',NaN),logical(field_or(fit,'valid',false)), ...
    string(field_or(fit,'message',"")),runtime_seconds,string(field_or(fit,'selector',"")), ...
    field_or(fit,'N_starts',NaN),field_or(fit,'valid_starts',NaN), ...
    string(field_or(fit,'penalty_mode',"")),field_or(fit,'tauW',NaN),field_or(fit,'tauT',NaN), ...
    string(field_or(fit,'init_pool_id',"")),string(field_or(fit,'selected_init_family',"")), ...
    field_or(fit,'selected_start_id',NaN),field_or(fit,'selected_start_seed',NaN), ...
    field_or(fit,'selected_objective_rank',NaN),field_or(fit,'selector_score',NaN), ...
    field_or(fit,'selector_cv_score',NaN), ...
    'VariableNames',{'scenario_id','replicate','seed','method','n','p','p_over_n','r0','c0', ...
    'arm','difficulty','delta','rho','contamination','alpha0','ari_inlier','trim_precision', ...
    'trim_recall','trim_f1','trim_tp','trim_fp','trim_fn','trim_count','objective','iterations', ...
    'valid','message','runtime_seconds','selector','N_starts','valid_starts','penalty_mode', ...
    'tauW','tauT','init_pool_id','selected_init_family','selected_start_id','selected_start_seed', ...
    'selected_objective_rank','selector_score','selector_cv_score'});
end
function v=field_or(s,name,default)
if isfield(s,name) && ~isempty(s.(name)), v=s.(name); else, v=default; end
end
